CustomField.formula:
IF( MONTH(Fecha_Inicio__c) = 1, IF( OR(
YEAR(Fecha_Inicio__c) = 2026
), IF( ISPICKVAL(Tipo_de_Mantencion__c, "Mantencion Mayor"), HYPERLINK( "/flow/Maintenance_Preview?recordId=" & Id & "&retURL=/" & $Label.Maintenance_Report_Calendar_Id, IMAGE($Label.Mantencion_Mayor_imagen, "Ver", 15, 100), "_parent" ), HYPERLINK( "/flow/Maintenance_Preview?recordId=" & Id & "&retURL=/" & $Label.Maintenance_Report_Calendar_Id, IMAGE($Label.Mantencion_de_Servicios_Imagen, "Ver", 15, 100), "_parent" ) ), "" ), "" )
